import{_ as d,l as s,o as a,c as i,v as o,p as c,x as t,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"DAX 与持久内存","description":"","frontmatter":{"title":"DAX 与持久内存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dax-pmem.md","filePath":"cs/dax-pmem.md","lastUpdated":1789023840000}'),m={name:"cs/dax-pmem.md"};function A(h,e,f,D,_,E){const r=s("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="dax-与持久内存" tabindex="-1">DAX 与持久内存 <a class="header-anchor" href="#dax-与持久内存" aria-label="Permalink to &quot;DAX 与持久内存&quot;">​</a></h1><div class="epigraph"><p>DAX 让文件系统把持久内存页直接映进用户地址空间：load/store 代替 read/write，但持久顺序要靠刷写指令，而不是块层 flush。</p><footer>—— 据 Linux DAX 文档；Intel 对持久内存编程模型的说明；Rudoff 对 SNIA NVM 编程的整理</footer></div><p><a href="/cs/bcache">上一课</a>仍是块 I/O。<a href="/cs/fs-mmap-coherence">mmap</a> 通常缺页从块设备填 DRAM。<a href="/cs/nvme-driver">NVMe</a> 再快也是完成队列。缺口是 <strong>持久内存 + DAX</strong>：介质可字节寻址，页缓存变成可选。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PMEM（或 CXL 内存的持久部分）出现在物理地址。FS（ext4/xfs dax、NOVA 等）可把文件映射到这些页，<code>MAP_SYNC</code> 等语义要求 store 到达持久点。缺口：CPU 缓存里的脏行不是持久的，需 <code>clwb</code>/<code>sfence</code> 或 <code>msync</code>；与 <a href="/cs/direct-io">O_DIRECT</a> 不同——没有 bio；与 tmpfs 不同——掉电还在（若刷对）。本课不把每一代 Optane 产品当目录。</p><p><span class="marginnote">falloc 预分配在 DAX 上仍占介质。错误 DRAM 与 PMEM 混映射会把易失当持久。教学对象是「绕过块层的 mmap」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>挂载 <code>dax</code>：<code>mmap</code> 建立直接映射，fault 填物理 PMEM pfn。<code>read</code>/<code>write</code> 仍可走拷贝路径或短期缓冲。崩溃一致：应用或库（PMDK）按失败原子粒度刷。对照 <a href="/cs/cow-filesystem">COW FS</a>：仍可在 PMEM 上 COW，只是拷贝是 <code>memcpy</code> 加刷写。对照块设备：没有 mq-deadline。</p>',8)),(a(),c(p,null,{default:t(()=>[n(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20MMAP%5B%22mmap%20DAX%22%5D%20--%3E%20PFN%5B%22%E6%8C%81%E4%B9%85%E5%86%85%E5%AD%98%E9%A1%B5%E5%B8%A7%22%5D%0A%20%20ST%5B%22store%22%5D%20--%3E%20CACHE%5B%22CPU%20%E7%BC%93%E5%AD%98%22%5D%0A%20%20CACHE%20--%3E%20FLUSH%5B%22clwb%20%E7%AD%89%E5%88%B0%E6%8C%81%E4%B9%85%E5%9F%9F%22%5D%0A%20%20FLUSH%20--%3E%20MEDIA%5B%22PMEM%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DAX 把存储栈变短：FS 负责分配与元数据，数据路径像内存。正确性从「bio 完成」换成「持久域可见性」，这是新的编程模型。不要把它写成量化超低延迟撮合。内核仍要管坏页、热插、fsck。</p><p>与加密：dm-crypt 在块层，DAX 常绕过它，需 FS 级或硬件加密。</p><p>实现上：CPU 缓存行刷到持久域的指令因平台而异，库（PMDK）把这封装成粒度。混合 DRAM 缓存的 FSDAX 若崩溃，DRAM 里那一层不是持久的。 读法上只引用<a href="/cs/bcache">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>DAX 与持久内存</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 <code>pmem</code> 命名空间模式（fsdax vs devdax）。不保证每个平台的持久域边界文档一致。下一课回到块设备，但完成等待换成轮询：io polling。</p><p>版本字段会变，课序钉的是机制对象「DAX 与持久内存」，不是某一主线内核的结构体名。 后课默认：PMEM 文件可 DAX 映射，持久靠刷写。块层用轮询代替中断收完成，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DAX 把 PMEM 映进页表，绕过块层数据路径。</li><li>持久顺序是 CPU 刷写，不是 NVMe 完成。</li><li>轮询 I/O 是下一课。</li><li>出处：Linux DAX；SNIA NVM 模型；ext4/xfs dax 文档。</li></ul>',11))])}const P=d(m,[["render",A]]);export{u as __pageData,P as default};
